"""web.config: written from a complete template only when there is none; an existing one is never replaced, only the
port in its Rewrite url is changed, so the team's own edits survive. Parsed back to verify either way."""
import os
import re
import xml.etree.ElementTree as ET

import config
from shell import DeployError

TEMPLATE = """<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by NextDeployer. On every deploy only the port in the Rewrite url below is updated. -->
<configuration>
  <system.webServer>
    <rewrite>
      <rules>
        <rule name="ReverseProxyToNode" stopProcessing="true">
          <match url="(.*)" />
          <action type="Rewrite" url="http://127.0.0.1:{port}/{{R:1}}" />
        </rule>
      </rules>
    </rewrite>
    <httpErrors existingResponse="PassThrough" />
    <handlers>
      <remove name="StaticFile" />
    </handlers>
    <security>
      <requestFiltering>
        <requestLimits maxAllowedContentLength="{max_bytes}" />
      </requestFiltering>
    </security>{websocket}
  </system.webServer>
</configuration>
"""
PORT_RE = re.compile(r'(url\s*=\s*"https?://127\.0\.0\.1:)\d+', re.I)


def render(port: int, max_bytes: int = config.MAX_UPLOAD_BYTES, websockets: bool = config.WEBSOCKETS) -> str:
    ws = '\n    <webSocket enabled="true" />' if websockets else ""
    return TEMPLATE.format(port=int(port), max_bytes=int(max_bytes), websocket=ws)


def validate(path: str, port: int) -> bool:
    try:
        actions = ET.parse(path).getroot().findall("./system.webServer/rewrite/rules/rule/action")
    except (ET.ParseError, OSError):
        return False
    return any(a.get("url", "").startswith(f"http://127.0.0.1:{port}/") for a in actions)


def write(folder: str, port: int) -> str:
    path = os.path.join(folder, "web.config")
    try:  # surrogateescape + newline="": everything except the port is written back byte for byte
        with open(path, encoding="utf-8", errors="surrogateescape", newline="") as f:
            old = f.read()
    except FileNotFoundError:
        old = None
    if old is None:
        with open(path, "w", encoding="utf-8", newline="\r\n") as f:
            f.write(render(port))
    elif PORT_RE.search(old):
        with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
            f.write(PORT_RE.sub(rf"\g<1>{int(port)}", old))
    else:
        raise DeployError("فایل web.config پوشه برنامه خط Rewrite به آدرس http://127.0.0.1:پورت را ندارد، "
                          "پس پورت آن قابل تنظیم نیست. فایل دست نخورد. به تیم فنی اطلاع دهید.")
    if not validate(path, port):
        raise DeployError("فایل تنظیمات IIS (web.config) درست ساخته نشد.")
    return path
